ALTER TABLE ALARMS
    ADD COLUMN CREATED_BY VARCHAR(64),
    ADD COLUMN CREATED_AT DATETIME DEFAULT CURRENT_TIMESTAMP,
    ADD COLUMN UPDATED_BY VARCHAR(64),
    ADD COLUMN UPDATED_AT DATETIME,
    ADD INDEX idx_begin (BEGIN_TIME);

