UPDATE ALARMS SET
    LENGHT = TIME_FORMAT(SEC_TO_TIME(TIMESTAMPDIFF(SECOND, BEGIN_TIME,
                 IF(END_TIME = '0000-00-00 00:00:00', NOW(), END_TIME))), '%H:%i:%s'),
    COMMON_PROSTOY = SEC_TO_TIME(LEAST(TIME_TO_SEC(PROSTOY) * GREATEST(NUMB_RBS, 1), 3020399));
